<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\ValueObject\Accessor\UserMfaRecoveryCodeCodeHashAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserMfaRecoveryCodeCodeHashAccessor trait.
 *
 * Covers null default, string/VO assignment via withCodeHash,
 * getCodeHash/codeHash accessors, and isCodeHashChanged with/without original.
 */
class UserMfaRecoveryCodeCodeHashAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withCodeHash creates a new instance with the CodeHash set
     * from a string value, and getCodeHash returns the primitive string.
     */
    public function testWithCodeHashFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserMfaRecoveryCodeCodeHashAccessorUnitTest();

        // Act
        $result = $holder->withCodeHash('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getCodeHash());
    }
    /**
     * Asserts that withcodeHash has access to the value object
     * from a string value, and getCodeHash returns the primitive string.
     */
    public function testWithCodeHashFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserMfaRecoveryCodeCodeHashAccessorUnitTest();

        // Act
        $result = $holder->withCodeHash('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->codeHash()->value());
    }
    public function testChangedCodeHash(): void
    {
        // Arrange
        $holder = new ImplWithUserMfaRecoveryCodeCodeHashAccessorUnitTest()->withCodeHash('one');
        $original = $holder->withCodeHash('one');
        $same = $holder->withCodeHash('one');
        $modified = $holder->withCodeHash('other');

        // Act
        $withSame = $original->isCodeHashChanged($same);
        $withDiferent = $original->isCodeHashChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserMfaRecoveryCodeCodeHashAccessorUnitTest
{
    use UserMfaRecoveryCodeCodeHashAccessor;
}
